import java.util.*;
import java.io.*;

public class Main {
    static int n_input, total_count, answer_value;
    static List<Integer>[] buckets = new ArrayList[15];
    static long[] prefix_sum = new long[15];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n_input = Integer.parseInt(br.readLine());
        for (int i = 0; i < 15; i++) {
            buckets[i] = new ArrayList<>();
        }
        generate_combinations(0, 0);
        for (int i = 0; i <= 7; i++) {
            Collections.sort(buckets[i]);
        }
        total_count = 0;
        answer_value = 0;
        for (int i = 1; i <= 9; i++) {
            process_number(i);
        }
        System.out.println(answer_value);
    }

    static void generate_combinations(int depth, int num) {
        if (depth == 7) return;
        total_count++;
        int val = (int)(((long)(total_count - num) % 998244353 + 998244353) % 998244353);
        buckets[depth].add(val);
        prefix_sum[depth] = (prefix_sum[depth] + val) % 1000000007;
        for (int digit = 0; digit <= 9; digit++) {
            generate_combinations(depth + 1, num * 10 + digit);
        }
    }

    static void process_number(int x) {
        if (x > n_input) return;
        if (x * 1000000 + 999999 <= n_input && x * 10000000 > n_input) {
            int current_total = total_count;
            for (int i = 0, factor = 1; i <= 6; i++, factor *= 10) {
                int size = buckets[i].size();
                long diff = ((long)(current_total - x * factor) % 998244353 + 998244353) % 998244353;
                int pos = lowerBound(buckets[i], (int)(1000000000 - diff));
                answer_value = (int)((answer_value + diff * size + prefix_sum[i]) % 1000000007);
                long subtractVal = (998244353L * (size - pos)) % 1000000007;
                answer_value = (int)((answer_value - subtractVal + 1000000007) % 1000000007);
                current_total += size;
            }
            return;
        }
        total_count++;
        long temp = ((long)(total_count - x) % 998244353 + 998244353) % 998244353;
        answer_value = (int)((answer_value + temp) % 1000000007);
        for (int digit = 0; digit <= 9; digit++) {
            process_number(x * 10 + digit);
        }
    }

    static int lowerBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
